"use client";

/**
 * Dashboard route (`/dashboard`).
 *
 * Orchestrates the multi-agent WebSocket hook, sidebar, chat panel, and
 * task panel. Clicking "+" or selecting "New Agent" sets `activeAgentId`
 * to `null`, which shows the spawn input. On spawn, the server responds
 * with `spawned` and the hook auto-selects the new agent.
 *
 * ## Loading states
 *
 * Two loading flags from the hook control the UI:
 * - `initialLoadDone` — false until the first `agent_list` arrives from
 *   the server. While false, the sidebar shows skeleton rows.
 * - `historyLoading` — true when the active agent's message history has
 *   not been fetched yet (lazy loading). The chat shows a "Loading
 *   messages..." indicator until the server responds.
 *
 * Sidebar uses `!initialLoadDone`, chat uses `!initialLoadDone || historyLoading`.
 */

import { useEffect, useState } from "react";
import { useWebSocket } from "@/hooks/use-websocket";
import { AgentSidebar } from "@/components/dashboard/agent-sidebar";
import { Chat } from "@/components/dashboard/chat";
import { TaskPanel, type TaskViewMode } from "@/components/dashboard/kanban-board";
import { FolderBrowser } from "@/components/dashboard/folder-browser";
import { cn } from "@/lib/utils";

export default function DashboardPage() {
  const {
    connected,
    initialLoadDone,
    historyLoading,
    agents,
    agentOrder,
    activeAgentId,
    setActiveAgentId,
    activeStatus,
    activeMessages,
    activeRawMessages,
    spawnAgent,
    sendMessage,
    respondToControl,
    respondToUserQuestion,
    killAgent,
    deleteAgent,
    renameAgent,
    clearHistory,
    tasks,
    createTask,
    updateTask,
    deleteTask,
    delegateTask,
    workspaces,
    activeWorkspaceId,
    setActiveWorkspaceId,
    createWorkspace,
    renameWorkspace,
    deleteWorkspace,
    browseDirectory,
    directoryListing,
  } = useWebSocket();

  const [taskView, setTaskView] = useState<"hidden" | TaskViewMode>("hidden");
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [folderBrowserOpen, setFolderBrowserOpen] = useState(false);

  // Derive initial path from first workspace or fallback to "/"
  const initialBrowsePath = workspaces.length > 0 ? workspaces[0].cwd : "/";

  useEffect(() => {
    document.title = "thos — dashboard";
  }, []);

  return (
    <div className="relative flex h-dvh overflow-hidden">
      {/* Sidebar backdrop (mobile only) */}
      {sidebarOpen && (
        <div
          className="fixed inset-0 z-40 bg-black/50 md:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar drawer */}
      <div
        className={cn(
          "fixed inset-y-0 left-0 z-50 w-56 transition-transform duration-200 ease-in-out md:relative md:z-auto md:translate-x-0 md:transition-none",
          sidebarOpen ? "translate-x-0" : "-translate-x-full"
        )}
      >
        <AgentSidebar
          agents={agents}
          agentOrder={agentOrder}
          activeAgentId={activeAgentId}
          loading={!initialLoadDone}
          onSelect={(id) => {
            setActiveAgentId(id);
            setSidebarOpen(false);
          }}
          onNewAgent={() => {
            setActiveAgentId(null);
            setSidebarOpen(false);
          }}
          onKill={killAgent}
          onDelete={deleteAgent}
          onRename={renameAgent}
          onClearHistory={clearHistory}
          workspaces={workspaces}
          activeWorkspaceId={activeWorkspaceId}
          onSelectWorkspace={setActiveWorkspaceId}
          onRenameWorkspace={renameWorkspace}
          onDeleteWorkspace={deleteWorkspace}
          onOpenFolder={() => setFolderBrowserOpen(true)}
        />
      </div>

      {/* Main chat area (hidden in board mode) */}
      <div className={cn("flex min-w-0 flex-1 flex-col", taskView === "board" && "hidden")}>
        <Chat
          connected={connected}
          loading={!initialLoadDone || historyLoading}
          status={activeStatus}
          messages={activeMessages}
          rawMessages={activeRawMessages}
          onSendMessage={sendMessage}
          onSpawnAgent={spawnAgent}
          onRespondToControl={respondToControl}
          onRespondToUserQuestion={respondToUserQuestion}
          onClearHistory={() => { if (activeAgentId) clearHistory(activeAgentId); }}
          showTasks={taskView !== "hidden"}
          onToggleTasks={() => setTaskView((v) => (v === "hidden" ? "list" : "hidden"))}
          onToggleSidebar={() => setSidebarOpen((v) => !v)}
        />
      </div>

      {/* Task panel backdrop (mobile only) */}
      {taskView !== "hidden" && (
        <div
          className="fixed inset-0 z-40 bg-black/50 md:hidden"
          onClick={() => setTaskView("hidden")}
        />
      )}

      {/* Task panel drawer */}
      {taskView !== "hidden" && (
        <div
          className={cn(
            "fixed inset-y-0 right-0 z-50 border-l bg-background flex flex-col min-w-0 md:relative md:z-auto",
            taskView === "board"
              ? "w-full max-w-none"
              : "w-80 max-w-[calc(100vw-3rem)] md:max-w-none"
          )}
        >
          <TaskPanel
            tasks={tasks}
            mode={taskView}
            onModeChange={(mode) => setTaskView(mode)}
            onCreateTask={createTask}
            onUpdateTask={updateTask}
            onDeleteTask={deleteTask}
            onDelegateTask={delegateTask}
            onSelectAgent={(agentId) => {
              setActiveAgentId(agentId);
            }}
            onClose={() => setTaskView("hidden")}
          />
        </div>
      )}

      {/* Folder browser modal */}
      <FolderBrowser
        open={folderBrowserOpen}
        onClose={() => setFolderBrowserOpen(false)}
        directoryListing={directoryListing}
        onBrowse={browseDirectory}
        onCreate={(name, cwd) => {
          createWorkspace(name, cwd);
          setFolderBrowserOpen(false);
        }}
        initialPath={initialBrowsePath}
      />
    </div>
  );
}

content.content:
  1→"use client";
  2→
  3→/**
  4→ * Main chat interface for the thos dashboard.
  5→ *
  6→ * Composes {@link StatusBar}, a scrollable message list ({@link Message}
  7→ * and {@link ControlRequest} cards), and an input bar. The submit button
  8→ * text toggles between "Spawn" (when idle/done) and "Send" (when an
  9→ * agent session is active). Auto-scrolls on new messages.
 10→ *
 11→ * A toggle in the top-right switches between the processed chat view
 12→ * and a raw JSON view of all Claude NDJSON messages.
 13→ *
 14→ * Receives all data and callbacks via props — the parent page component
 15→ * owns the WebSocket hook and orchestrates multiple agents.
 16→ */
 17→
 18→import { useEffect, useMemo, useRef, useState } from "react";
 19→import type { AgentStatus, ChatMessage, ClaudeMessage } from "@/lib/types";
 20→import { condenseMessages } from "@/lib/condense-messages";
 21→import { StatusBar } from "./status-bar";
 22→import { Message } from "./message";
 23→import { ControlRequest } from "./control-request";
 24→import { UserQuestion } from "./user-question";
 25→import { CondensedToolGroup } from "./condensed-tool-group";
 26→import { SlashCommandMenu, filterCommands, type SlashCommand } from "./slash-command-menu";
 27→import { Button } from "@/components/ui/button";
 28→
 29→export function Chat({
 30→  connected,
 31→  loading,
 32→  status,
 33→  messages,
 34→  rawMessages,
 35→  onSendMessage,
 36→  onSpawnAgent,
 37→  onRespondToControl,
 38→  onRespondToUserQuestion,
 39→  onClearHistory,
 40→  showTasks,
 41→  onToggleTasks,
 42→  onToggleSidebar,
 43→}: {
 44→  connected: boolean;
 45→  loading?: boolean;
 46→  status: AgentStatus;
 47→  messages: ChatMessage[];
 48→  rawMessages: ClaudeMessage[];
 49→  onSendMessage: (content: string) => void;
 50→  onSpawnAgent: (prompt: string) => void;
 51→  onRespondToControl: (requestId: string, allow: boolean) => void;
 52→  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
 53→  onClearHistory?: () => void;
 54→  showTasks?: boolean;
 55→  onToggleTasks?: () => void;
 56→  onToggleSidebar?: () => void;
 57→}) {
 58→  const [input, setInput] = useState("");
 59→  const [showRaw, setShowRaw] = useState(false);
 60→  const [showSlashMenu, setShowSlashMenu] = useState(false);
 61→  const [slashQuery, setSlashQuery] = useState("");
 62→  const [slashHighlight, setSlashHighlight] = useState(0);
 63→  const scrollRef = useRef<HTMLDivElement>(null);
 64→  const inputRef = useRef<HTMLInputElement>(null);
 65→
 66→  useEffect(() => {
 67→    scrollRef.current?.scrollTo({
 68→      top: scrollRef.current.scrollHeight,
 69→      behavior: "smooth",
 70→    });
 71→  }, [messages, rawMessages, showRaw]);
 72→
 73→  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
 74→  const isActive = status === "connected" || status === "thinking";
 75→  const isArchived = status === "done" || status === "disconnected" || status === "error";
 76→
 77→  function handleSubmit(e: React.FormEvent) {
 78→    e.preventDefault();
 79→    const trimmed = input.trim();
 80→    if (!trimmed) return;
 81→
 82→    if (isActive) {
 83→      onSendMessage(trimmed);
 84→    } else {
 85→      onSpawnAgent(trimmed);
 86→    }
 87→    setInput("");
 88→    setShowSlashMenu(false);
 89→  }
 90→
 91→  function handleInputChange(e: React.ChangeEvent<HTMLInputElement>) {
 92→    const value = e.target.value;
 93→    setInput(value);
 94→
 95→    if (value.startsWith("/")) {
 96→      setShowSlashMenu(true);
 97→      setSlashQuery(value.slice(1));
 98→      setSlashHighlight(0);
 99→    } else {
100→      setShowSlashMenu(false);
101→      setSlashQuery("");
102→    }
103→  }
104→
105→  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
106→    if (!showSlashMenu) return;
107→    const filtered = filterCommands(slashQuery);
108→    if (filtered.length === 0) return;
109→
110→    if (e.key === "ArrowDown") {
111→      e.preventDefault();
112→      setSlashHighlight((i) => (i + 1) % filtered.length);
113→    } else if (e.key === "ArrowUp") {
114→      e.preventDefault();
115→      setSlashHighlight((i) => (i - 1 + filtered.length) % filtered.length);
116→    } else if (e.key === "Enter") {
117→      e.preventDefault();
118→      handleCommandSelect(filtered[slashHighlight]);
119→    } else if (e.key === "Escape") {
120→      e.preventDefault();
121→      setShowSlashMenu(false);
122→    } else if (e.key === "Tab") {
123→      e.preventDefault();
124→      setInput(`/${filtered[slashHighlight].name} `);
125→      setShowSlashMenu(false);
126→    }
127→  }
128→
129→  function handleCommandSelect(command: SlashCommand) {
130→    setShowSlashMenu(false);
131→    setSlashQuery("");
132→    setInput("");
133→
134→    if (command.clientSide) {
135→      if (command.name === "clear") {
136→        onClearHistory?.();
137→      }
138→      return;
139→    }
140→
141→    const commandText = `/${command.name}`;
142→    if (isActive) {
143→      onSendMessage(commandText);
144→    } else {
145→      onSpawnAgent(commandText);
146→    }
147→  }
148→
149→  return (
150→    <div className="flex h-full flex-col">
151→      <StatusBar
152→        connected={connected}
153→        status={status}
154→        showRaw={showRaw}
155→        onToggleRaw={() => setShowRaw((v) => !v)}
156→        showTasks={showTasks}
157→        onToggleTasks={onToggleTasks}
158→        onToggleSidebar={onToggleSidebar}
159→      />
160→
161→      <div ref={scrollRef} className="flex-1 overflow-y-auto p-2 md:p-4 space-y-2">
162→        {loading ? (
163→          <div className="flex h-full flex-col items-center justify-center gap-3">
164→            <div className="flex gap-1">
165→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse" />
166→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:150ms]" />
167→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:300ms]" />
168→            </div>
169→            <span className="text-xs text-muted-foreground">
170→              {connected ? "Loading messages..." : "Connecting..."}
171→            </span>
172→          </div>
173→        ) : showRaw ? (
174→          rawMessages.length === 0 ? (
175→            <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
176→              No raw messages yet
177→            </div>
178→          ) : (
179→            <div className="space-y-1">
180→              {rawMessages.map((msg, i) => (
181→                <RawMessage key={i} message={msg} index={i} />
182→              ))}
183→            </div>
184→          )
185→        ) : (
186→          <>
187→            {messages.length === 0 && (
188→              <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
189→                Type a prompt to spawn a Claude agent
190→              </div>
191→            )}
192→            {displayItems.map((item) => {
193→              if (item.kind === "condensed") {
194→                return <CondensedToolGroup key={item.id} group={item} />;
195→              }
196→              const msg = item.message;
197→              return msg.userQuestion ? (
198→                <UserQuestion
199→                  key={msg.id}
200→                  message={msg}
201→                  onRespond={onRespondToUserQuestion}
202→                />
203→              ) : msg.controlRequest ? (
204→                <ControlRequest
205→                  key={msg.id}
206→                  message={msg}
207→                  onRespond={onRespondToControl}
208→                />
209→              ) : (
210→                <Message key={msg.id} message={msg} />
211→              );
212→            })}
213→          </>
214→        )}
215→      </div>
216→
217→      {isArchived && messages.length > 0 ? (
218→        <div className="border-t px-4 py-2 text-center text-xs text-muted-foreground">
219→          This session has ended
220→        </div>
221→      ) : (
222→        <form
223→          onSubmit={handleSubmit}
224→          className="relative flex gap-2 border-t px-2 py-2 md:px-4 md:py-3"
225→        >
226→          {showSlashMenu && (
227→            <SlashCommandMenu
228→              query={slashQuery}
229→              highlightedIndex={slashHighlight}
230→              onSelect={handleCommandSelect}
231→              onHighlight={setSlashHighlight}
232→            />
233→          )}
234→          <input
235→            ref={inputRef}
236→            type="text"
237→            value={input}
238→            onChange={handleInputChange}
239→            onKeyDown={handleKeyDown}
240→            placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
241→            className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
242→          />
243→          <Button type="submit" disabled={!connected || !input.trim()}>
244→            {isActive ? "Send" : "Spawn"}
245→          </Button>
246→        </form>
247→      )}
248→    </div>
249→  );
250→}
251→
252→/** Badge color per Claude NDJSON message type. */
253→const TYPE_COLORS: Record<string, string> = {
254→  system: "text-yellow-500",
255→  assistant: "text-blue-400",
256→  result: "text-green-500",
257→  control_request: "text-orange-400",
258→  keep_alive: "text-muted-foreground",
259→};
260→
261→function RawMessage({ message, index }: { message: ClaudeMessage; index: number }) {
262→  const [expanded, setExpanded] = useState(false);
263→  const subtype = (message as { subtype?: string }).subtype;
264→  const typeLabel = subtype ? `${message.type}/${subtype}` : message.type;
265→  const colorClass = TYPE_COLORS[message.type] ?? "text-muted-foreground";
266→
267→  return (
268→    <div className="font-mono text-[11px] leading-relaxed">
269→      <button
270→        onClick={() => setExpanded((v) => !v)}
271→        className="flex w-full items-center gap-2 rounded px-2 py-1 text-left hover:bg-muted/50 transition-colors"
272→      >
273→        <span className="text-muted-foreground w-6 shrink-0 text-right">{index}</span>
274→        <span className={colorClass}>{typeLabel}</span>
275→        <span className="text-muted-foreground">{expanded ? "▼" : "▶"}</span>
276→      </button>
277→      {expanded && (
278→        <pre className="ml-10 overflow-x-auto rounded bg-muted/30 p-2 text-[10px] text-muted-foreground whitespace-pre-wrap break-all">
279→          {JSON.stringify(message, null, 2)}
280→        </pre>
281→      )}
282→    </div>
283→  );
284→}
285→

